def solve(I):
    H,W=len(I),len(I[0])
    bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    out=[r[:] for r in I]
    for rmin in range(H):
        for cmin in range(W):
            cc=I[rmin][cmin]
            if cc==bg: continue
            for rmax in range(rmin+2,H):
                for cmax in range(cmin+2,W):
                    if any(I[rmin][c]!=cc for c in range(cmin,cmax+1)): continue
                    if any(I[rmax][c]!=cc for c in range(cmin,cmax+1)): continue
                    if any(I[r][cmin]!=cc for r in range(rmin,rmax+1)): continue
                    if any(I[r][cmax]!=cc for r in range(rmin,rmax+1)): continue
                    inter=[I[r][c] for r in range(rmin+1,rmax) for c in range(cmin+1,cmax)]
                    if bg in inter and all(x in (cc,bg) for x in inter):
                        area=(rmax-rmin-1)*(cmax-cmin-1)
                        fill=7 if area%2 else 2
                        for r in range(rmin+1,rmax):
                            for c in range(cmin+1,cmax):
                                if out[r][c]==bg: out[r][c]=fill
    return out

